// TIKTOK SHOP ANALYTICS NIGHTLY — 02:30 giờ VN. Kéo CHỈ SỐ MARKETING (phễu · sản phẩm · video · live)
// + đơn AFFILIATE cấp dòng SKU từ TikTok Shop Open API vào Bronze cho mục /marketing.
//
// BẤT BIẾN #2: mọi con số ở đây là SỐ SÀN TỰ NHẬN CÔNG. Chỉ hiển thị THAM KHẢO trong khu riêng có
// nhãn. TUYỆT ĐỐI KHÔNG lấy làm doanh thu, không sửa phí sàn, không đối chiếu "lệch" với đơn Pancake.
//
// TOKEN — CHỈ ĐỌC, KHÔNG REFRESH, KHÔNG GHI. TikTok XOAY VÒNG refresh_token (refresh xong là cái cũ
// chết ngay) ⇒ chỉ được DUY NHẤT MỘT hệ refresh, và hệ đó là `tiktokshop-nightly` chạy lúc 02:00,
// tức 30 phút trước lượt này. Nếu workflow này cũng refresh thì hai lượt đốt token của nhau và chuỗi
// ĐỐI SOÁT TIỀN đang LIVE đứt — mất dữ liệu tiền để đổi lấy vài chỉ số marketing. Token hỏng ⇒ THROW
// nêu rõ phải kiểm lượt 02:00.
//
// BẤT BIẾN payload: KHÔNG parse JSON của stream dữ liệu (`json:false` + `encoding:"text"`); chuỗi thô
// đi thẳng sang app, Postgres cast ::jsonb. HAI ngoại lệ có chủ đích: (a) lời gọi ĐỌC kho token (chỉ
// có token + epoch, không có int64); (b) bước LÀM PHẲNG affiliate — xem docblock lamPhangDonAffiliate:
// mọi id int64 của endpoint đó là CHUỖI (đo 28/08), có cổng THROW nếu hợp đồng đổi.
//
// TIÊU CHÍ NGHIỆM THU — `ngay` PHẢI LÀ NGÀY GIỜ VN (bất biến #3). Mã dưới đây tính ngày bằng
// `Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Ho_Chi_Minh" })` nên độc lập TZ của container/runner,
// NHƯNG không có phép kiểm máy nào trong repo chứng minh được điều đó cho lượt chạy THẬT (code chạy
// trong task-runner của n8n, ngoài tầm với của vitest). Nghiệm thu bằng tay ở lượt rollout:
//   1. Chạy tay một lượt, đọc `window.tu` / `window.den` trong output — phải đúng dải ngày GIỜ VN
//      (neo "hôm qua giờ VN"), kể cả khi bấm chạy trong khung 00:00–07:00 VN.
//   2. `SELECT DISTINCT "externalId" FROM app."RawTiktokShopAnalyticsProduct" ORDER BY 1 DESC LIMIT 5`
//      — phần trước dấu ':' phải là đúng những ngày đó, KHÔNG lệch một nhịp.
//
// SECRET: nằm ở view `app."SettingN8n"` — node "Lấy khoá từ bảng Setting" chạy trước và truyền xuống.
const KHOA = Object.fromEntries($input.all().map((i) => [i.json.key, i.json.value]));
if (!Object.keys(KHOA).length) {
  throw new Error(
    'Node "Lấy khoá từ bảng Setting" không trả về dòng nào — kiểm credential Postgres ' +
      '(role n8n_config_ro) và view app."SettingN8n".'
  );
}

const CONFIG = {
  base: "https://open-api.tiktokglobalshop.com",
  appUrl: KHOA.n8nAppUrl,
  ingestSecret: KHOA.n8nIngestSecret,
  appKey: KHOA.tiktokShopAppKey,
  appSecret: KHOA.tiktokShopAppSecret,
  shopCipher: KHOA.tiktokShopCipher,
  // shopId TikTok Shop Open API — KHÁC id shop TikTok bên Pancake. App CHẶN nếu điền nhầm.
  shopId: KHOA.tiktokShopShopId,
  // Trần CỨNG do chính API nói ra: 36009004 "PageSize is invalid, check validation rule is:
  // $this > 0 && $this <= 100". Đừng nâng.
  pageSize: 100,
  pageDelayMs: 1200, // ≈50 request/phút — analytics khuyến nghị 0,2–1 req/s
  // Cửa sổ mặc định 3 ngày: sàn chỉnh số hồi tố vài ngày (cùng triết lý cửa sổ updated_at 3 ngày của
  // Pancake), và Bronze dedupe theo hash nên chồng lấn miễn phí.
  nightlyDays: 3,
  // Cửa sổ đêm RIÊNG của khối (5) affiliate — 60 ngày (chủ shop chốt 28/08 tối, sau phép đo): khối (5) lọc theo
  // create_time của ĐƠN mà hoa hồng chỉ chốt SAU khi giao (trễ giao TB 3,94 / max 17 ngày, đo 28/08) ⇒ 3 ngày chưa
  // phủ nổi khâu giao, đơn "đang chờ sàn chốt" không bao giờ được kéo lại. 60 = đúng 1 lát (LAT_NGAY_AFFILIATE) ⇒
  // vẫn 1 cổng Σ == total_count; lưu lượng hiện tại ≈ 1 trang/đêm; Bronze KHÔNG phình (hash không đổi ⇒ DO NOTHING).
  // KHÔNG đụng nightlyDays của 4 stream analytics (2 request/NGÀY; 3 ngày đủ vì sàn chỉ chỉnh số hồi tố vài ngày).
  nightlyDaysAffiliate: 60,
};

const KHOA_THIEU = Object.entries({
  n8nAppUrl: CONFIG.appUrl,
  n8nIngestSecret: CONFIG.ingestSecret,
  tiktokShopAppKey: CONFIG.appKey,
  tiktokShopAppSecret: CONFIG.appSecret,
  tiktokShopCipher: CONFIG.shopCipher,
  tiktokShopShopId: CONFIG.shopId,
})
  .filter(([, v]) => !v)
  .map(([k]) => k);
if (KHOA_THIEU.length) {
  throw new Error(
    'THIẾU KHOÁ trong bảng app."Setting": ' + KHOA_THIEU.join(", ") +
      ". Thêm dòng key/value tương ứng rồi chạy lại — không cần đụng file cấu hình hay dựng lại container."
  );
}

/** Trần trang mỗi lượt gọi. Chạm trần mà còn token = CẮT CỤT ⇒ THROW (không thoát êm). */
const MAX_PAGES = 200;
/**
 * TRẦN 90 NGÀY cho cửa sổ ép tay. Đây là trần VẬT LÝ: 90 ngày × 2 endpoint theo ngày × ~1 trang
 * ≈ 190 request × 1,2s ≈ 4 phút — vẫn xa trần 3600s của runner, nhưng rộng hơn thì chạm rate-limit
 * và không mua thêm gì (sàn chỉ chỉnh số hồi tố vài ngày).
 */
const MAX_MANUAL_DAYS = 90;
/**
 * AFFILIATE — key ép cửa sổ RIÊNG `tiktokShopAffiliateManualDays`, trần 365 ngày, CHỈ đổi cửa sổ khối (5).
 * Vì sao tách khỏi MAX_MANUAL_DAYS: 90 là trần VẬT LÝ của analytics (2 request/NGÀY), còn affiliate kéo
 * theo LÁT 60 ngày (đo 28/08: 13 trang/60 ngày cao điểm) ⇒ 365 ngày ≈ 7 lát ≈ vài chục request. Đơn
 * affiliate T3–T4/2026 (253 dòng SKU) nằm ngoài 90 ngày ⇒ không có key riêng thì KHÔNG BAO GIỜ vào app.
 * 4 stream analytics KHÔNG đọc key này (vẫn theo soNgay). Đặt key → chạy → XOÁ key, như các key kia.
 */
const MAX_AFFILIATE_MANUAL_DAYS = 365;
/**
 * AFFILIATE — trần lát cửa sổ 60 ngày + page_size 20: CHỌN SỐ ĐÃ ĐO (probe 28/08 chạy cửa sổ 61
 * ngày + page_size 20, HTTP 200 code 0), KHÔNG chọn số tài liệu nói (spec nói cửa sổ 3 tháng;
 * trần page_size chưa đo — analytics trần 100 nhưng đó là endpoint KHÁC). Cửa sổ ép tay dài hơn
 * 60 ngày được khối (5) TỰ CHIA LÁT, mỗi lát một cổng đếm riêng.
 */
const LAT_NGAY_AFFILIATE = 60;
const PAGE_SIZE_AFFILIATE = 20;

const http = this.helpers.httpRequest;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const nowSec = () => Math.floor(Date.now() / 1000);
const DAY_MS = 86400000;

/**
 * Đọc số ngày ép từ một ô của bảng Setting. Trả 0 = KHÔNG ép. CHỈ nhận số nguyên 1..tran; mọi giá trị
 * khác ⇒ THROW. (Bản sao có chủ đích của `soNgayCuaSo` trong 3 workflow nightly kia — n8n không import
 * chéo được; BỐN bản phải đổi cùng nhau, `tests/ingest/cua-so-ngay-workflow-nightly.test.ts` so từng
 * chữ giữa các bản.)
 */
function soNgayCuaSo(key, giaTri, tran) {
  const s = String(giaTri === undefined || giaTri === null ? "" : giaTri).trim();
  if (s === "") return 0;
  if (!/^[0-9]+$/.test(s) || Number(s) < 1 || Number(s) > tran) {
    throw new Error(
      "Key " + key + ' = "' + s + '" KHÔNG hợp lệ — chỉ nhận SỐ NGUYÊN từ 1 đến ' + tran +
        " (không thập phân, không số âm, không chữ, không Infinity). Sửa lại ô đó trong bảng " +
        'app."Setting", hoặc XOÁ/để trống nó để quay về cửa sổ mặc định, rồi chạy lại.'
    );
  }
  return Number(s);
}

// Ngày theo GIỜ VN, KHÔNG theo TZ container. en-CA ⇒ đúng khuôn "YYYY-MM-DD".
const vnFmt = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Ho_Chi_Minh",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});
const vnDate = (ms) => vnFmt.format(new Date(ms));
/** Cộng/trừ ngày trên chuỗi YYYY-MM-DD. Hai đầu đều là nửa đêm UTC ⇒ không dính chuyển múi giờ. */
function congNgay(d, n) {
  return new Date(Date.parse(d + "T00:00:00Z") + n * DAY_MS).toISOString().slice(0, 10);
}
/** Epoch GIÂY tại 00:00 giờ VN của ngày YYYY-MM-DD — offset +07:00 tường minh, độc lập TZ máy chạy. */
function epochGiayVn(d) {
  return Math.floor(Date.parse(d + "T00:00:00+07:00") / 1000);
}
/**
 * Cửa sổ khối (5) affiliate — hai đầu đóng, ngày giờ VN, neo `den` = hôm qua (KHÔNG neo hôm nay: đơn hôm nay
 * chưa chốt). Có key riêng ⇒ [den − (soNgayAff − 1) .. den]; không có key ⇒ [den − (macDinhNgay − 1) .. den] với
 * macDinhNgay = CONFIG.nightlyDaysAffiliate. HOÀN TOÀN ĐỘC LẬP với cửa sổ 4 stream analytics (tuNgay/soNgay):
 * hàm cố ý KHÔNG nhận tham số nào của analytics để không thể vô tình dùng chung. Hàm thuần để test cắt ra chạy thật.
 */
function cuaSoAffiliate(soNgayAff, macDinhNgay, den) {
  if (soNgayAff > 0) {
    return {
      tu: congNgay(den, -(soNgayAff - 1)),
      den: den,
      mode: "cửa sổ ép " + soNgayAff + " ngày (key tiktokShopAffiliateManualDays)",
    };
  }
  return {
    tu: congNgay(den, -(macDinhNgay - 1)),
    den: den,
    mode: "mặc định " + macDinhNgay + " ngày (nightlyDaysAffiliate — không có key tiktokShopAffiliateManualDays)",
  };
}
/**
 * Chia [tu..den] thành các lát ≤ latNgay ngày, liền kề, không hở không chồng (lát cuối có thể ngắn).
 * Mỗi lát một lượt keoLuotAffiliate = một cổng đếm Σ == total_count riêng.
 */
function cacLatAffiliate(tu, den, latNgay) {
  const lat = [];
  for (let latTu = tu; latTu <= den; ) {
    const cuoiLat = congNgay(latTu, latNgay - 1);
    const latDen = cuoiLat < den ? cuoiLat : den;
    lat.push([latTu, latDen]);
    latTu = congNgay(latDen, 1);
  }
  return lat;
}

const soNgayEp = soNgayCuaSo("tiktokShopAnalyticsManualDays", KHOA.tiktokShopAnalyticsManualDays, MAX_MANUAL_DAYS);
const soNgayEpAffiliate = soNgayCuaSo("tiktokShopAffiliateManualDays", KHOA.tiktokShopAffiliateManualDays, MAX_AFFILIATE_MANUAL_DAYS);
const soNgay = soNgayEp > 0 ? soNgayEp : CONFIG.nightlyDays;
// Neo vào HÔM QUA giờ VN: hôm nay chắc chắn chưa chốt, và mốc sẵn sàng của sàn còn trễ hơn nữa.
const denNgay = vnDate(Date.now() - DAY_MS);
const tuNgay = congNgay(denNgay, -(soNgay - 1));
const danhSachNgay = [];
for (let d = tuNgay; d <= denNgay; d = congNgay(d, 1)) danhSachNgay.push(d);

const logs = [];
const results = [];
/**
 * Mốc dữ liệu sẵn sàng THEO TỪNG endpoint — ĐỌC từ `latest_available_date` của chính envelope, KHÔNG
 * suy ra từ một hằng độ trễ. Checkpoint P2 (25/08) đo: mốc trôi khác nhau theo endpoint VÀ theo giờ
 * (00:15 shop 23/08 vs products 22/08; 14:12 shop 24/08 vs products 22/08) ⇒ hard-code kiểu "products
 * chậm 1 ngày" là sai ngay trong ngày.
 */
const mocSanSang = {};
let token = { accessToken: "", expireAt: 0 };

/**
 * CẢNH BÁO (KHÔNG chặn) cho hai stream kéo theo CẢ CỬA SỔ — `shop/performance` và `shop_lives`.
 * Chúng land MỘT lượt cho cả dải ngày nên KHÔNG đi qua cổng mốc sẵn sàng trong `keoLuot`: cổng đó
 * chỉ chạy khi có `ngayBom`, mà hai lượt này truyền `null`. Checkpoint P2 đo: lúc 00:15 mốc của
 * `shop/performance` là 23/08 trong khi "hôm qua" đã là 24/08 ⇒ lượt 02:30 gần như ĐÊM NÀO CŨNG hỏi
 * ít nhất một ngày vượt mốc, và A14 mục 1 đo được sàn trả `code=0` kèm SỐ DỞ DANG (không phải rỗng).
 * Không có dòng cảnh báo này thì đêm nào lệch cũng không để lại dấu vết nào trong execution.
 *
 * CỐ Ý KHÔNG kéo lại lần 2, KHÔNG cắt cửa sổ, KHÔNG chặn land:
 *  (a) CHƯA ĐO `shop/performance` trả gì cho ngày vượt mốc (mới đo `shop_products`) — đo 1 request ở
 *      lượt rollout rồi mới quyết, đừng đoán;
 *  (b) dữ liệu TỰ LÀNH trong ≤2 đêm: cửa sổ 3 ngày LĂN nên ngày dở dang được kéo lại ở 1–2 đêm sau,
 *      và reader đọc `latestPayloads` (`fetchedAt DESC`) nên bản mới đè bản dở;
 *  (c) số của 4 stream này nằm NGOÀI P&L (bất biến #2) — lệch một đêm là lệch chỉ số THAM KHẢO, không
 *      sai một đồng tiền nào. Chặn cứng ở đây chỉ đổi "số hơi dở" lấy "không có số".
 */
function canhBaoVuotMoc(stream, lad) {
  if (!lad || denNgay <= lad) return;
  logs.push({
    level: "CANH_BAO",
    message: stream + ": kéo cả cửa sổ tới " + denNgay + " nhưng sàn mới chốt số tới " + lad +
      " — mọi ngày SAU " + lad + " là SỐ DỞ DANG (sàn trả code=0 kèm số chưa chốt, KHÔNG rỗng), " +
      "đừng đọc thành ngày ế. Không chặn: cửa sổ lăn sẽ kéo lại trong ≤2 đêm và reader lấy bản mới " +
      "nhất; số này nằm ngoài P&L.",
  });
}

/** HMAC-SHA256 hex — bản sao của `tiktokshop-nightly` (n8n không import chéo được). */
async function hmacSha256Hex(secret, message) {
  try {
    const nodeCrypto = require("crypto");
    if (nodeCrypto && nodeCrypto.createHmac) {
      return nodeCrypto.createHmac("sha256", secret).update(message, "utf8").digest("hex");
    }
  } catch (e) {
    // require bị chặn → rơi xuống WebCrypto
  }
  const subtle = globalThis.crypto && globalThis.crypto.subtle;
  if (!subtle) {
    throw new Error(
      "Không ký được HMAC: thiếu cả require('crypto') lẫn WebCrypto. " +
        "Đặt NODE_FUNCTION_ALLOW_BUILTIN=crypto cho container n8n."
    );
  }
  const enc = new TextEncoder();
  const key = await subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await subtle.sign("HMAC", key, enc.encode(message));
  return Array.from(new Uint8Array(sig))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/** Chữ ký TikTok: HMAC(app_secret, app_secret + path + Σ(key+value đã SORT, bỏ sign & access_token) + body + app_secret). */
async function signQuery(path, qs, bodyText) {
  const keys = Object.keys(qs)
    .filter((k) => k !== "sign" && k !== "access_token")
    .sort();
  const joined = keys.map((k) => k + qs[k]).join("");
  // GET truyền thiếu bodyText => "" — chuỗi ký y hệt bản cũ, không đổi một bit chữ ký đang chạy.
  return hmacSha256Hex(CONFIG.appSecret, CONFIG.appSecret + path + joined + (bodyText || "") + CONFIG.appSecret);
}

/**
 * ĐỌC token từ kho token của app. CHỈ GET — không refresh, không POST (xem đầu file).
 * Kho rỗng hoặc token đã hết hạn ⇒ THROW ngay, TRƯỚC khi bắn request dữ liệu nào.
 */
async function loadToken() {
  let res;
  try {
    res = await http({
      method: "GET",
      url: CONFIG.appUrl + "/api/ingest/tiktok-token",
      headers: { Authorization: "Bearer " + CONFIG.ingestSecret },
      json: true,
    });
  } catch (err) {
    throw new Error(
      "KHÔNG ĐỌC ĐƯỢC KHO TOKEN của app (" + CONFIG.appUrl + "/api/ingest/tiktok-token): " +
        ((err && err.message) || String(err))
    );
  }
  if (!res || !res.accessToken) {
    throw new Error(
      "KHO TOKEN CỦA APP RỖNG. Workflow analytics CHỈ ĐỌC token — cấp lại bằng " +
        "scripts/tiktok-shop-lay-token.ts rồi nạp qua POST /api/ingest/tiktok-token."
    );
  }
  token = { accessToken: res.accessToken, expireAt: Number(res.accessTokenExpireAt) || 0 };
  const conGio = token.expireAt > 0 ? Math.round((token.expireAt - nowSec()) / 3600) : null;
  if (token.expireAt > 0 && token.expireAt <= nowSec()) {
    throw new Error(
      "ACCESS TOKEN ĐÃ HẾT HẠN (epoch " + token.expireAt + "). Workflow này KHÔNG được gia hạn " +
        "(TikTok xoay vòng refresh_token, chỉ 1 hệ refresh) — token do `tiktokshop-nightly` 02:00 gia " +
        "hạn, kiểm lượt chạy đó."
    );
  }
  logs.push({ level: "INFO", message: "Đọc token từ app, còn " + conGio + "h" });
}

const BACKOFF_MS = [5000, 15000, 45000, 120000, 300000];
function laLoiTamThoi(err) {
  const code = String((err && (err.httpCode || err.statusCode || (err.response && err.response.status))) || "");
  const msg = (err && err.message) || String(err);
  return code === "429" || /^5\d\d$/.test(code) || /status code (429|5\d\d)/.test(msg);
}

const LOI_TOKEN =
  " — workflow analytics KHÔNG gia hạn token (chỉ `tiktokshop-nightly` 02:00 được refresh, vì TikTok " +
  "xoay vòng refresh_token). Kiểm lượt chạy 02:00 đêm nay.";

/** GET 1 trang TEXT THÔ. KHÔNG refresh token trong mọi tình huống. 429/5xx thì lùi rồi thử lại. */
async function getRaw(path, params, lanThu) {
  lanThu = lanThu || 0;
  const qs = Object.assign({}, params, {
    app_key: CONFIG.appKey,
    timestamp: nowSec(),
    shop_cipher: CONFIG.shopCipher,
  });
  qs.sign = await signQuery(path, qs);

  let text;
  try {
    text = await http({
      method: "GET",
      url: CONFIG.base + path,
      qs,
      headers: { "x-tts-access-token": token.accessToken },
      json: false,
      encoding: "text", // BẮT BUỘC: thiếu nó axios vẫn parse
    });
  } catch (err) {
    const code = String((err && (err.httpCode || err.statusCode)) || "");
    if (code === "401" || code === "403" || /status code (401|403)/.test((err && err.message) || "")) {
      throw new Error("GET " + path + " bị từ chối (HTTP " + code + ")" + LOI_TOKEN);
    }
    if (laLoiTamThoi(err) && lanThu < BACKOFF_MS.length) {
      const cho = BACKOFF_MS[lanThu];
      logs.push({
        level: "CANH_BAO",
        message: path + ": TikTok nghẽn (429/5xx), chờ " + cho / 1000 + "s rồi thử lại (lần " +
          (lanThu + 1) + "/" + BACKOFF_MS.length + ")",
      });
      await sleep(cho);
      return getRaw(path, params, lanThu + 1);
    }
    throw new Error("GET " + path + " lỗi: " + ((err && err.message) || String(err)));
  }

  if (typeof text !== "string") {
    throw new Error("n8n trả object cho " + path + ", không phải TEXT thô — thiếu encoding:'text'.");
  }

  // TikTok trả HTTP 200 kèm `code` ≠ 0 khi từ chối ⇒ soi code bằng REGEX trên chuỗi thô.
  const codeMatch = text.match(/"code"\s*:\s*(-?\d+)/);
  const apiCode = codeMatch ? Number(codeMatch[1]) : null;
  if (apiCode !== 0) {
    const msg = (text.match(/"message"\s*:\s*"([^"]*)"/) || [])[1] || "";
    if (apiCode === 105005) {
      throw new Error(
        "THIẾU SCOPE cho " + path + " (code 105005). Bật scope tương ứng ở Partner Center → App & " +
          "Service → Manage API, rồi CẤP QUYỀN LẠI theo runbook n8n/huong-dan-cai-dat-workflows.md. " +
          'Thông điệp sàn: "' + msg + '"'
      );
    }
    if (apiCode === 105002 || /token|auth/i.test(msg)) {
      throw new Error("TikTok từ chối " + path + ": code=" + apiCode + ' message="' + msg + '"' + LOI_TOKEN);
    }
    throw new Error(
      "TikTok từ chối " + path + ": code=" + apiCode + ' message="' + msg + '" — bộ tham số là HẰNG ' +
        "trong workflow, đổi phải sửa code + probe lại, KHÔNG nuốt lỗi."
    );
  }
  return text;
}

/**
 * POST 1 trang TEXT THÔ — bản POST của getRaw, cho endpoint affiliate orders/search. Chữ ký PHẢI
 * gộp body (app_secret + path + Σ(key+value đã SORT) + body + app_secret): ký thiếu body thì sign
 * sai và TikTok trả 401 — rất dễ đọc nhầm thành "mất scope". KHÔNG refresh token trong mọi tình
 * huống (cùng luật getRaw). 429/5xx thì lùi rồi thử lại.
 */
async function postRaw(path, params, bodyText, lanThu) {
  lanThu = lanThu || 0;
  const qs = Object.assign({}, params, {
    app_key: CONFIG.appKey,
    timestamp: nowSec(),
    shop_cipher: CONFIG.shopCipher,
  });
  qs.sign = await signQuery(path, qs, bodyText);

  let text;
  try {
    text = await http({
      method: "POST",
      url: CONFIG.base + path,
      qs,
      headers: { "x-tts-access-token": token.accessToken, "content-type": "application/json" },
      body: bodyText,
      json: false,
      encoding: "text", // BẮT BUỘC: thiếu nó axios vẫn parse
    });
  } catch (err) {
    const code = String((err && (err.httpCode || err.statusCode)) || "");
    if (code === "401" || code === "403" || /status code (401|403)/.test((err && err.message) || "")) {
      throw new Error("POST " + path + " bị từ chối (HTTP " + code + ") — kiểm CẢ chữ ký có gộp body chưa (ký thiếu body cũng ra 401)" + LOI_TOKEN);
    }
    if (laLoiTamThoi(err) && lanThu < BACKOFF_MS.length) {
      const cho = BACKOFF_MS[lanThu];
      logs.push({
        level: "CANH_BAO",
        message: path + ": TikTok nghẽn (429/5xx), chờ " + cho / 1000 + "s rồi thử lại (lần " +
          (lanThu + 1) + "/" + BACKOFF_MS.length + ")",
      });
      await sleep(cho);
      return postRaw(path, params, bodyText, lanThu + 1);
    }
    throw new Error("POST " + path + " lỗi: " + ((err && err.message) || String(err)));
  }

  if (typeof text !== "string") {
    throw new Error("n8n trả object cho " + path + ", không phải TEXT thô — thiếu encoding:'text'.");
  }

  // TikTok trả HTTP 200 kèm `code` khác 0 khi từ chối — soi code bằng REGEX trên chuỗi thô.
  const codeMatch = text.match(/"code"\s*:\s*(-?\d+)/);
  const apiCode = codeMatch ? Number(codeMatch[1]) : null;
  if (apiCode !== 0) {
    const msg = (text.match(/"message"\s*:\s*"([^"]*)"/) || [])[1] || "";
    if (apiCode === 105005) {
      throw new Error(
        "THIẾU SCOPE cho " + path + " (code 105005). Bật scope Affiliate (Seller) ở Partner Center → App & " +
          "Service → Manage API, rồi CẤP QUYỀN LẠI theo runbook n8n/huong-dan-cai-dat-workflows.md. " +
          'Thông điệp sàn: "' + msg + '"'
      );
    }
    if (apiCode === 105002 || /token|auth/i.test(msg)) {
      throw new Error("TikTok từ chối " + path + ": code=" + apiCode + ' message="' + msg + '"' + LOI_TOKEN);
    }
    throw new Error(
      "TikTok từ chối " + path + ": code=" + apiCode + ' message="' + msg + '" — bộ tham số là HẰNG ' +
        "trong workflow, đổi phải sửa code + probe lại, KHÔNG nuốt lỗi."
    );
  }
  return text;
}

/** Rút một trường CHUỖI khỏi envelope bằng regex (không JSON.parse). Không thấy ⇒ null. */
function docChuoi(text, key) {
  const m = text.match(new RegExp('"' + key + '"\\s*:\\s*"([^"]*)"'));
  return m ? m[1] : null;
}
/** Rút một trường SỐ NGUYÊN khỏi envelope. Không thấy ⇒ null. */
function docSo(text, key) {
  const m = text.match(new RegExp('"' + key + '"\\s*:\\s*(\\d+)'));
  return m ? Number(m[1]) : null;
}

/**
 * POST NGUYÊN chuỗi thô sang app. `ngay` chỉ gửi cho stream khai `chapNhanNgay` (app TỪ CHỐI 400 nếu
 * gửi sai chỗ hoặc thiếu chỗ cần) — record của products/videos không mang trường ngày nào.
 * Trả `seen`/`skippedNoId` để dựng cổng đối chứng với `total_count`.
 */
async function land(stream, text, ngay) {
  const body = { stream: stream, shopId: CONFIG.shopId, payload: text };
  if (ngay) body.ngay = ngay;
  const r = await http({
    method: "POST",
    url: CONFIG.appUrl + "/api/ingest/raw",
    json: true,
    headers: { Authorization: "Bearer " + CONFIG.ingestSecret },
    body: body,
  });
  const st = (r && r.stats) || {};
  const kq = {
    landed: Number(st.landed) || 0,
    seen: Number(st.seen) || 0,
    skippedNoId: Number(st.skippedNoId) || 0,
  };
  results.push({ stream: stream, ngay: ngay || null, landed: kq.landed, seen: kq.seen });
  return kq;
}

/**
 * Kéo HẾT trang của MỘT lượt (một ngày, hoặc cả cửa sổ với stream không theo ngày) rồi land từng trang.
 *
 * KÊU TO, KHÔNG NUỐT LẶNG:
 *  - `ngayBom` mà vượt `latest_available_date` ⇒ KHÔNG land, trả boQua (đừng ghi ngày sàn chưa chốt:
 *    checkpoint P2 đo THẬT — sàn trả `code=0` kèm số DỞ DANG, không phải rỗng, nên Bronze sẽ có một
 *    ngày trông y như ngày ế thật; Bronze append-only nên sửa không được).
 *  - `total_count === 0` ⇒ KHÔNG land (xem cổng ngay trong vòng lặp).
 *  - `next_page_token` lặp không đổi ⇒ THROW. Chạm trần trang mà còn token ⇒ THROW.
 *  - Σ(seen + skippedNoId) ≠ `data.total_count` ⇒ THROW: trang bị cắt cụt mà execution vẫn xanh là
 *    kiểu hỏng tệ nhất (thiếu số, không ai biết).
 */
async function keoLuot(path, stream, params, ngayBom) {
  let pageToken = "";
  let lad = null;
  let tongCount = null;
  let tongRecord = 0;
  let guard = 0;

  for (;;) {
    const qs = Object.assign({}, params, { page_size: CONFIG.pageSize, currency: "LOCAL" });
    if (pageToken) qs.page_token = pageToken;

    const text = await getRaw(path, qs);

    if (guard === 0) {
      lad = docChuoi(text, "latest_available_date");
      if (ngayBom && lad && ngayBom > lad) return { lad: lad, boQua: true };
      tongCount = docSo(text, "total_count");
    }

    // CỔNG CHECKPOINT P2 (đo thật 25/08) — PHẢI đứng TRƯỚC `land`.
    // Trang 0 record ⇒ TikTok BỎ HẲN khoá mảng (`data.products` biến mất) dù `code=0`. `landRaw`
    // (`src/lib/bronze/land-raw.ts`) khi đó THROW với thông điệp đổ oan "hết hạn key / token /
    // rate-limit" — TRÙNG cơ chế workflow này dùng để bắt lỗi scope 105005 / tham số 36009004 ⇒ hai
    // ca không phân biệt được, nightly đỏ và người đọc đi sai hướng điều tra cả đêm. Ngày thật sự
    // không có record là chuyện BÌNH THƯỜNG (ngày ế), không phải sự cố.
    if (guard === 0 && tongCount === 0) {
      logs.push({
        level: "INFO",
        message: stream + " " + (ngayBom || "cả cửa sổ") + ": total_count=0 — KHÔNG land (trang rỗng " +
          "không có khoá mảng, land vào sẽ báo lỗi token/rate-limit sai sự thật)",
      });
      return { lad: lad, boQua: false, rong: true };
    }

    const st = await land(stream, text, ngayBom);
    tongRecord += st.seen + st.skippedNoId;
    guard++;

    const next = docChuoi(text, "next_page_token") || "";
    if (!next) break;
    if (next === pageToken) {
      throw new Error(
        "PHÂN TRANG KẸT ở " + path + ": next_page_token không đổi (\"" + next + "\") sau trang " + guard +
          " — dừng để không kéo vô hạn và không cắt cụt trong im lặng."
      );
    }
    if (guard >= MAX_PAGES) {
      throw new Error(
        path + ": chạm trần " + MAX_PAGES + " trang mà VẪN CÒN next_page_token — dữ liệu sẽ bị CẮT CỤT."
      );
    }
    pageToken = next;
    await sleep(CONFIG.pageDelayMs);
  }

  // CỔNG CHỐNG CẮT CỤT — GIỮ CHẶT, KHÔNG NỚI.
  // `seen` của app là số khoá PHÂN BIỆT thấy trong trang, `skippedNoId` là record không rút được khoá.
  // Nếu hai record trong CÙNG MỘT TRANG trùng khoá thì tổng này nhỏ hơn `total_count` và cổng đỏ —
  // đó là đỏ ĐÚNG, không phải oan: khoá trùng nghĩa là một record CHE record kia ở mọi đường đọc theo
  // `externalId` (Bronze append-only, `DISTINCT ON` chỉ giữ một bản) ⇒ dữ liệu đã hỏng từ nguồn.
  // Đừng "sửa cổng cho hết oan" bằng cách đếm record thô — làm vậy là bịt đúng cái đèn báo.
  if (tongCount !== null && tongRecord !== tongCount) {
    throw new Error(
      path + (ngayBom ? " ngày " + ngayBom : "") + ": app nhận " + tongRecord + " record nhưng sàn báo " +
        "total_count=" + tongCount + " — trang bị cắt cụt hoặc khoá record trùng nhau. DỪNG."
    );
  }
  return { lad: lad, boQua: false };
}

/** Kéo 1 request/NGÀY cho endpoint mà record không mang trường ngày (products, videos). */
async function keoTheoNgay(path, stream, extra) {
  let lad = null;
  let daKeo = 0;
  for (const d of danhSachNgay) {
    if (lad && d > lad) {
      logs.push({ level: "INFO", message: path + ": dừng ở " + d + " — sàn mới có số tới " + lad });
      break;
    }
    const kq = await keoLuot(
      path,
      stream,
      Object.assign({ start_date_ge: d, end_date_lt: congNgay(d, 1) }, extra),
      d
    );
    if (kq.lad) lad = kq.lad;
    if (kq.boQua) {
      logs.push({
        level: "CANH_BAO",
        message: path + ": ngày " + d + " vượt mốc sẵn sàng " + kq.lad + " — KHÔNG land (sàn trả số dở dang)",
      });
      break;
    }
    daKeo++;
    await sleep(CONFIG.pageDelayMs);
  }
  mocSanSang[stream] = lad;
  return daKeo;
}

/**
 * LÀM PHẲNG payload affiliate: data.orders[].skus[] → mỗi dòng SKU một record, bơm 4 trường cấp
 * đơn xuống từng dòng (mã đơn THẬT là 'id', KHÔNG phải 'order_id' — đo 28/08). Land theo DÒNG SKU
 * vì khoá Bronze append-only: land theo đơn thì đơn có SKU vắt qua 2 trang sẽ bị trang sau ghi đè
 * bản skus THIẾU lên bản đủ — mất dòng, không log nào đỏ.
 *
 * NGOẠI LỆ CÓ CHỦ ĐÍCH của bất biến không-parse-JSON: bước làm phẳng buộc phải parse. An toàn vì
 * đo thật 28/08: MỌI id int64 của endpoint này là CHUỖI ('id', 'sku_id', 'product_id',
 * 'content_id', 'open_collaboration_id'); số duy nhất là epoch giây / quantity / total_count —
 * đều < 2^53. Hai cổng dưới THROW nếu hợp đồng đổi (id thành SỐ là JSON.parse làm tròn int64).
 */
function lamPhangDonAffiliate(text) {
  const goc = JSON.parse(text);
  const data = goc && goc.data ? goc.data : {};
  const totalCount = typeof data.total_count === "number" ? data.total_count : null;
  // total_count=0: TikTok nhiều khả năng bỏ hẳn khoá mảng (cùng lớp checkpoint P2) — trả sớm để
  // keoLuotAffiliate KHÔNG land, tránh landRaw ném thông điệp đổ oan token/rate-limit.
  if (totalCount === 0) return { payload: null, totalCount: 0, nextPageToken: "", soDonKhongSku: 0 };
  if (!Array.isArray(data.orders)) {
    throw new Error(
      "affiliate orders/search trả envelope KHÔNG có mảng 'data.orders' (code=0) — hợp đồng API " +
        "đã đổi. KHÔNG land: land vào sẽ báo lỗi token/rate-limit sai sự thật."
    );
  }
  const records = [];
  let soDonKhongSku = 0;
  for (const o of data.orders) {
    if (typeof o.id !== "string") {
      throw new Error(
        "affiliate orders/search: 'id' của đơn không còn là CHUỖI (typeof=" + typeof o.id +
          ") — JSON.parse làm tròn int64, khoá Bronze sẽ hỏng vĩnh viễn. KHÔNG land, probe lại."
      );
    }
    if (!Number.isInteger(o.create_time) || o.create_time <= 0) {
      throw new Error(
        "affiliate orders/search: 'create_time' của đơn " + o.id + " không phải epoch giây hợp lệ (nhận " +
          JSON.stringify(o.create_time) + ") — 'null * 1000' là 0 ⇒ _ngay thành ngày ma 1970-01-01 và đi vòng " +
          "qua MỌI lưới kiểm ngày của landRaw (stream này không dùng tham số 'ngay'). KHÔNG land."
      );
    }
    const ngayDon = vnDate(o.create_time * 1000);
    // Cùng cửa sổ hợp lý với landRaw (NGAY_SOM_NHAT 2024-01-01 … ngày mai giờ VN) — Bronze
    // append-only, một điểm ma trong chuỗi _ngay là nằm vĩnh viễn và reader lọc kỳ sẽ vẽ/ẩn nó câm.
    if (ngayDon < "2024-01-01" || ngayDon > vnDate(Date.now() + DAY_MS)) {
      throw new Error(
        "affiliate orders/search: đơn " + o.id + " có _ngay = " + ngayDon + " ngoài cửa sổ hợp lý " +
          "[2024-01-01 … ngày mai giờ VN] — nhiều khả năng create_time sai đơn vị (mili giây?) hoặc " +
          "hợp đồng đổi. KHÔNG land."
      );
    }
    const dsSku = Array.isArray(o.skus) ? o.skus : [];
    // Đơn 0 dòng SKU là trạng thái CÓ THẬT ở sàn (đơn mới, chưa quy công) — không THROW, nhưng
    // phải ĐẾM để keoLuotAffiliate ghi vết, không nuốt im lặng (review 28/08).
    if (dsSku.length === 0) soDonKhongSku++;
    for (const sk of dsSku) {
      if (typeof sk.sku_id !== "string") {
        throw new Error(
          "affiliate orders/search: 'sku_id' không còn là CHUỖI (typeof=" + typeof sk.sku_id +
            ") — JSON.parse làm tròn int64, khoá Bronze sẽ hỏng vĩnh viễn. KHÔNG land, probe lại."
        );
      }
      // 3 trường id int64 còn lại (không bắt buộc có, nhưng CÓ thì phải là CHUỖI): fixture đo
      // content_id 7629572620026924306 / product_id 1731910711337911979 đều > 2^53 — TikTok đổi
      // sang số JSON là parse làm tròn ngay mà không cổng nào khác bắt (review 28/08).
      for (const truongId of ["product_id", "content_id", "open_collaboration_id"]) {
        if (sk[truongId] !== undefined && typeof sk[truongId] !== "string") {
          throw new Error(
            "affiliate orders/search: '" + truongId + "' không còn là CHUỖI (typeof=" + typeof sk[truongId] +
              ") — JSON.parse làm tròn int64 (>2^53), giá trị sai nằm vĩnh viễn trong Bronze. KHÔNG land, probe lại."
          );
        }
      }
      records.push(Object.assign({}, sk, {
        _don_id: o.id,
        _create_time: o.create_time, // epoch giây, kiểu NUMBER (đo 28/08)
        _delivery_time: o.delivery_time,
        _ngay: ngayDon, // YYYY-MM-DD giờ VN đã qua cổng cửa sổ hợp lý ở trên — reader lọc kỳ bằng CHUỖI
      }));
    }
  }
  return {
    payload: JSON.stringify({ data: { orders: records } }),
    totalCount: totalCount,
    nextPageToken: typeof data.next_page_token === "string" ? data.next_page_token : "",
    soDonKhongSku: soDonKhongSku,
  };
}

/**
 * Kéo HẾT trang affiliate của MỘT lát cửa sổ [tu..den] (ngày giờ VN, hai đầu đóng) rồi land từng
 * trang ĐÃ LÀM PHẲNG. Lọc theo create_time của ĐƠN, biên = nửa đêm giờ VN.
 *
 * CỔNG ĐẾM: Σ(seen + skippedNoId) so với total_count — total_count của TikTok đếm DÒNG SKU,
 * KHÔNG đếm đơn (đo 28/08: page_size 20 trả 19 đơn / 20 dòng SKU). Đếm ĐƠN ở đây là THROW OAN
 * trên hệ khoẻ (19 đơn vs total_count 253 dòng). seen của app là số khoá PHÂN BIỆT: hai dòng
 * trùng khoá (don_id, sku_id) trong cùng trang làm tổng hụt và cổng đỏ — đỏ ĐÚNG, vì khoá trùng
 * nghĩa là một dòng CHE dòng kia ở mọi đường đọc DISTINCT ON. Đừng sửa cổng cho hết oan.
 */
async function keoLuotAffiliate(tu, den) {
  const path = "/affiliate_seller/202410/orders/search";
  const stream = "tiktok/affiliate_orders";
  const bodyText = JSON.stringify({
    create_time_ge: epochGiayVn(tu),
    create_time_lt: epochGiayVn(congNgay(den, 1)),
  });
  let pageToken = "";
  let tongCount = null;
  let tongDong = 0;
  let tongDonKhongSku = 0;
  let guard = 0;

  for (;;) {
    const qs = { page_size: PAGE_SIZE_AFFILIATE };
    if (pageToken) qs.page_token = pageToken;

    const text = await postRaw(path, qs, bodyText);
    const phang = lamPhangDonAffiliate(text);

    if (guard === 0) {
      tongCount = phang.totalCount;
      if (tongCount === null) {
        throw new Error(
          path + ": không đọc được 'total_count' (vắng khoá hoặc không còn là number) — cổng chống cắt " +
            "cụt là lưới DUY NHẤT của stream này, mất chỗ dựa thì không land trang nào. Hợp đồng API " +
            "đã đổi, probe lại. KHÔNG land."
        );
      }
      if (tongCount === 0) {
        logs.push({
          level: "INFO",
          message: stream + " " + tu + ".." + den + ": total_count=0 — KHÔNG land (kỳ không có " +
            "đơn affiliate là bình thường; trang rỗng không có khoá mảng, land vào sẽ báo lỗi " +
            "token/rate-limit sai sự thật)",
        });
        return { dongSku: 0, rong: true };
      }
    }

    if (phang.payload === null) {
      // total_count=0 ở trang ≥2: sàn đổi tập kết quả GIỮA chừng phân trang. Không kiểm thì luồng
      // rơi xuống land(null) → app 400 "thiếu shopId hoặc payload" — thông điệp chỉ sai hướng hoàn toàn.
      throw new Error(
        path + ": total_count=0 xuất hiện Ở TRANG " + (guard + 1) + " giữa chừng phân trang — sàn đổi " +
          "tập kết quả trong lúc kéo. DỪNG, chạy lại lượt."
      );
    }
    tongDonKhongSku += phang.soDonKhongSku;
    const st = await land(stream, phang.payload);
    tongDong += st.seen + st.skippedNoId;
    guard++;

    const next = phang.nextPageToken || "";
    if (!next) break;
    if (next === pageToken) {
      throw new Error(
        "PHÂN TRANG KẸT ở " + path + ": next_page_token không đổi (\"" + next + "\") sau trang " + guard +
          " — dừng để không kéo vô hạn và không cắt cụt trong im lặng."
      );
    }
    if (guard >= MAX_PAGES) {
      throw new Error(
        path + ": chạm trần " + MAX_PAGES + " trang mà VẪN CÒN next_page_token — dữ liệu sẽ bị CẮT CỤT."
      );
    }
    pageToken = next;
    await sleep(CONFIG.pageDelayMs);
  }

  // CỔNG CHỐNG CẮT CỤT — GIỮ CHẶT, KHÔNG NỚI (xem docblock: đếm DÒNG SKU, không đếm đơn).
  if (tongCount !== null && tongDong !== tongCount) {
    throw new Error(
      path + " " + tu + ".." + den + ": app nhận " + tongDong + " dòng SKU nhưng sàn báo " +
        "total_count=" + tongCount + " — trang bị cắt cụt hoặc khoá (don_id, sku_id) trùng nhau. DỪNG."
    );
  }
  if (tongDonKhongSku > 0) {
    logs.push({
      level: "CANH_BAO",
      message: path + " " + tu + ".." + den + ": " + tongDonKhongSku + " đơn KHÔNG có dòng SKU nào " +
        "(sàn chưa quy công?) — các đơn đó không land được dòng nào, chỉ ghi vết để khỏi mất dấu.",
    });
  }
  return { dongSku: tongDong, rong: false };
}

// ---------- CHẠY ----------
await loadToken();

// (1) PHỄU — 1 request cho CẢ cửa sổ (granularity=1D ⇒ mỗi interval một ngày). Envelope không có
// total_count và không phân trang; `latest_available_date` ở đây là mốc của riêng endpoint này.
const textShop = await getRaw("/analytics/202509/shop/performance", {
  start_date_ge: tuNgay,
  end_date_lt: congNgay(denNgay, 1),
  granularity: "1D",
  currency: "LOCAL",
});
const nptShop = docChuoi(textShop, "next_page_token") || "";
if (nptShop) {
  throw new Error(
    "shop/performance trả next_page_token (\"" + nptShop + "\") — endpoint này trước nay không phân " +
      "trang. Hợp đồng API đã đổi, phải probe lại trước khi tin số."
  );
}
// Endpoint này KHÔNG có `total_count` nên không dùng được cổng trang-rỗng ở `keoLuot`. Lưới thay thế:
// soi thẳng khoá mảng `intervals`. Vắng khoá ⇒ THROW Ở ĐÂY với lý do ĐÚNG, thay vì để `landRaw` ném
// thông điệp đổ oan token/rate-limit (cùng lớp lỗi checkpoint P2 mục 2). Mảng RỖNG (`"intervals": []`)
// vẫn đi tiếp bình thường — land 0 dòng không phải lỗi.
if (!/"intervals"\s*:\s*\[/.test(textShop)) {
  throw new Error(
    "shop/performance trả envelope KHÔNG có mảng 'intervals' (code=0) — hợp đồng API đã đổi hoặc cửa " +
      "sổ ngày vô nghĩa. KHÔNG land: land vào sẽ báo lỗi token/rate-limit sai sự thật."
  );
}
mocSanSang["tiktok/analytics_shop"] = docChuoi(textShop, "latest_available_date");
canhBaoVuotMoc("tiktok/analytics_shop", mocSanSang["tiktok/analytics_shop"]);
await land("tiktok/analytics_shop", textShop);

// (2) SẢN PHẨM và (3) VIDEO — record là TỔNG cả cửa sổ và KHÔNG có trường ngày ⇒ 1 request/ngày,
// app bơm `_ngay` vào khoá. Đi từ ngày CŨ NHẤT để đọc được `latest_available_date` ngay ở lượt đầu
// mà không tốn request thăm dò nào.
const ngayProducts = await keoTheoNgay("/analytics/202605/shop_products/performance", "tiktok/analytics_products", {});
const ngayVideos = await keoTheoNgay("/analytics/202605/shop_videos/performance", "tiktok/analytics_videos", {
  account_type: "ALL",
});

// (4) LIVE — phiên có `id` riêng và có `start_time`, không cần bơm ngày ⇒ kéo theo CẢ cửa sổ.
// `account_type` chỉ nhận ALL | OFFICIAL_ACCOUNTS | MARKETING_ACCOUNTS | AFFILIATE_ACCOUNTS
// (chính API nói ra ở lỗi 36009004) — ALL để lấy cả phiên của creator.
const kqLive = await keoLuot(
  "/analytics/202509/shop_lives/performance",
  "tiktok/analytics_lives",
  { start_date_ge: tuNgay, end_date_lt: congNgay(denNgay, 1), account_type: "ALL" },
  null
);
mocSanSang["tiktok/analytics_lives"] = kqLive.lad;
canhBaoVuotMoc("tiktok/analytics_lives", kqLive.lad);

// (5) AFFILIATE — đơn quy công cho creator, cấp DÒNG SKU (POST có body — chữ ký gộp body, xem
// postRaw). Cửa sổ RIÊNG, độc lập với tuNgay/denNgay của analytics: có key tiktokShopAffiliateManualDays
// thì [hôm qua − (N−1) .. hôm qua] (trần 365), không có thì mặc định CONFIG.nightlyDaysAffiliate (60 ngày,
// = đúng 1 lát); đổi sang epoch giây giờ VN; dài hơn LAT_NGAY_AFFILIATE thì chia lát, mỗi lát một cổng đếm
// riêng. Envelope KHÔNG có latest_available_date (data chỉ có orders/total_count/next_page_token — đo 28/08)
// nên không có mốc sẵn sàng để ghi.
// ⚠️ ĐÃ BIẾT, CHẤP NHẬN: đơn chốt muộn hơn 60 ngày kể từ ngày TẠO thì số settlement đứng yên tới lượt ép key
// tiktokShopAffiliateManualDays kế tiếp (rẻ: chỉ khối này). Đo 28/08: refresh KHÔNG đổi con số hoa hồng UI
// (estimated_paid_* = actual_paid_* trên 165 dòng SETTLED) — giá trị của cửa sổ rộng là đưa đơn "đang chờ sàn
// chốt" → "đã chốt". Số ngoài P&L (bất biến #2).
const cuaSoAff = cuaSoAffiliate(soNgayEpAffiliate, CONFIG.nightlyDaysAffiliate, denNgay);
const cacLatAff = cacLatAffiliate(cuaSoAff.tu, cuaSoAff.den, LAT_NGAY_AFFILIATE);
if (cacLatAff.length === 0) {
  // Cửa sổ rỗng (tu > den) chỉ xảy ra khi nightlyDaysAffiliate bị sửa thành ≤ 0 — 0 lát = đêm đó không kéo gì
  // mà không log, không đỏ. THROW để lộ ngay thay vì hỏng câm.
  throw new Error(
    "khối affiliate: cửa sổ rỗng " + cuaSoAff.tu + ".." + cuaSoAff.den + " (0 lát) — kiểm CONFIG.nightlyDaysAffiliate " +
      "(phải là số nguyên ≥ 1) hoặc key tiktokShopAffiliateManualDays."
  );
}
if (soNgayEpAffiliate > 0) {
  // Nhắc XOÁ key sau backfill — tiền lệ thật: tiktokShopManualDays=7 sót từ 25/07 tới 28/08 không ai thấy
  // vì tín hiệu duy nhất chìm trong JSON output. Đưa lên logs để đọc execution là thấy ngay.
  logs.push({
    level: "CANH_BAO",
    message: "khối affiliate đang chạy cửa sổ ép " + soNgayEpAffiliate + " ngày (" + cacLatAff.length +
      " lát ≤" + LAT_NGAY_AFFILIATE + " ngày, " + cuaSoAff.tu + ".." + cuaSoAff.den + ") — " +
      "XOÁ key tiktokShopAffiliateManualDays trong app.\"Setting\" ngay sau lượt này, nếu không mỗi đêm sẽ kéo lại chừng đó.",
  });
}
const affiliate = {
  dongSku: 0,
  luot: 0,
  mode: cuaSoAff.mode,
  window: { tu: cuaSoAff.tu, den: cuaSoAff.den },
  soLat: cacLatAff.length,
};
for (let i = 0; i < cacLatAff.length; i++) {
  const kqAff = await keoLuotAffiliate(cacLatAff[i][0], cacLatAff[i][1]);
  affiliate.luot++;
  affiliate.dongSku += kqAff.dongSku;
  if (i + 1 < cacLatAff.length) await sleep(CONFIG.pageDelayMs);
}

const landedTotal = results.reduce((s, r) => s + (Number(r.landed) || 0), 0);
return [
  {
    json: {
      mode: soNgayEp > 0 ? "cửa sổ ép " + soNgayEp + " ngày (key tiktokShopAnalyticsManualDays)" : "mặc định " + CONFIG.nightlyDays + " ngày (nightlyDays — 4 stream analytics; khối affiliate xem affiliate.mode)",
      execMode: $execution.mode,
      soNgay: soNgay,
      window: { tu: tuNgay, den: denNgay },
      ngayDaKeo: { products: ngayProducts, videos: ngayVideos },
      affiliate: affiliate,
      mocSanSang: mocSanSang,
      calls: results.length,
      landedTotal: landedTotal,
      logs: logs,
      results: results,
    },
  },
];
